pub(super) fn render_image(
    &mut self,
    svg: &mut SvgElem,
    state: &State,
    image: &Image,
    size: &Axes<Abs>,
) {
    let url = WebImage::new(image).to_base64_url();
    let mut svg = svg.elem("image");
    if !state.transform.is_identity() {
        svg.attr("transform", SvgTransform(state.transform));
    }
